data.query:
query OrderLineRelease($where: OrderLineReleaseWhereInput, $orderBy: [OrderLineReleaseOrderByInput!], $first: Int, $after: String) {
  orderLineRelease(where: $where, orderBy: $orderBy, first: $first, after: $after){
    edges{
      node{
        number
        allowOverage
        allowPartial
        quantity{ value unitId}
        orderLineReleaseStatusId
        receiptLineOrderLineReleases{
          edges{
            node{
              receiptLine{
                quantity{
                  _aggregate{
                    value{ sum }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.responseTransform:
{
  "success": false,
  "message": "The request for a receipt line of " & $state.context.INPUT.receiptLine.quantity.value & " would over fufill the required quantity. This is not allowed for this release."
}

{
  "success": false,
  "message": "The request for a receipt line of " & $state.context.INPUT.receiptLine.quantity.value & " would only partially fufill the required quantity. This is not allowed for this release."
}

{
  "success": false,
  "message": "This release can not be received against anymore."
}

data.mutation:
mutation CreateReceiptLine($receiptLinePayload: [ReceiptLineCreatePayloadInput!]!, $receiptLineOrderLineReleasePayload: [ReceiptLineOrderLineReleaseCreatePayloadInput!]!) {
  createReceiptLine(payload: $receiptLinePayload) {
    id
    number
  }
  createReceiptLineOrderLineRelease(payload: $receiptLineOrderLineReleasePayload) {
    id
  }
}

